head.script:
scwin.playwright = {
    'formatter' : false,
    'onadaptivechange' : false,
    'onpageindexchange' : false
};
scwin.onpageload = function() {
    scwin.createData();

    var isPass;
    // 렌더링 테스트
    isPass = scwin.checkRender();
    console.log("checkRender : [" + (isPass === true ? "PASS" : "FAIL") + "]");

    // 속성 테스트
    isPass = scwin.checkAdaptive();
    console.log("checkAdaptive : [" + (isPass === true ? "PASS" : "FAIL") + "]");

    isPass = scwin.checkDataList(); 
    console.log("checkDataList : [" + (isPass === true ? "PASS" : "FAIL") + "]");

    isPass = scwin.checkOtherProperty();
    console.log("checkOtherProperty : [" + (isPass === true ? "PASS" : "FAIL") + "]");

    // API 테스트 - get
    isPass = scwin.cardView_getApiTest();
    console.log("cardView_getApiTest : [" + (isPass === true ? "PASS" : "FAIL") + "]");

};

// rendering 
scwin.checkRender = function() {
    var comp = $p.getComponentById('cardView1')
    var dom = comp.render;

    var pageSize = cardView1.getPageSize();
    var domSize = document.getElementsByClassName('w2cardView_item').length
    var pageList = cardView1.pageList.render

    if((comp && dom) && (pageSize === domSize) && pageList) return true;
    return false;
}

// playWright 검증 로직 작성 시작 구간.
// Property, Event
// adaptive, adaptiveThreshold, adaptiveFormatter 동작 확인.
scwin.checkAdaptive = function() {
    // adaptive가 true, adaptiveThreshold 값에 따른 col 설정 동작이 됐는 지 확인한다.
    var colClass = document.getElementById('mf_cardView1_container').className;
    var isAdaptive = colClass.indexOf('adaptive_2') > 0 ? true : false;
    var isFormatter = cardView1.options.adaptiveFormatter !== '' && scwin.playwright.formatter;

    return isAdaptive && isFormatter;
}

// DataList 바인딩
scwin.checkDataList = function() {
    var arr = [
        cardView1._dataList.getCellData(0, 'col1'),
        dlt_test.getCellData(0, 'col1'),
        Number(cardView1.getCellComponentByColId(0, "col1")[0].getValue(), 10)
    ];

    return arr.every(v => v === 2);
}

// pageSize, usePageList, rowGap
scwin.checkOtherProperty = function() {
    var isSize = cardView1.getPageSize() === document.getElementsByClassName("w2cardView_item").length;
    var isPageList = cardView1.render && cardView1.pageList;
    var isRowGap = cardView1.render.childNodes[0].style.rowGap === '15px';

    return isSize && isPageList && isRowGap;
}

scwin.adaptiveFormatter = function(info) {
    console.log("adaptiveFormatter Check");
    console.log("columnCount :" + info.columnCount)
    console.log("rowCount : " + info.rowCount)
    console.log("startRow : " + info.startRow)
    console.log("width : " + info.width)

    scwin.playwright.formatter = true;
}; 

// Event
scwin.cardView1_onadaptivechange = function(info) {
    console.log("onadaptivechange : [PASS]");
    scwin.playwright.onadaptivechange = true;
}

scwin.cardView1_onpageindexchange = function(info) {
    console.log("onpageindexchange : [PASS]");
    scwin.playwright.onpageindexchange = true;
}

scwin.changeIndex = function() {
    cardView1.setPageIndex(5);
    return cardView1.getPageIndex() === 5;
}



// API 
// get
scwin.cardView_getApiTest = function() {
    try{
        var isPass = true;
        var arr = [
            cardView1.getCellComponentById(0, 'autoComplete'),
            cardView1.getCellComponentByColId(0, 'col10'),
            cardView1.getRowIndex('mf_cardView1_1_inputBox'),
            cardView1.getViewIndex('mf_cardView1_1_inputBox'),
            cardView1.getViewRowCount('mf_cardView1_1_inputBox'),
            cardView1.getPageIndex(),
            cardView1.getPageSize()
        ];

        var testAnswer = [
            $p.getComponentById("mf_cardView1_0_autoComplete"),
            $p.getComponentById('mf_cardView1_0_textbox17'),
            1,
            1,
            10,
            1,
            10
        ]

        arr.every((val, index) => {
            if(val != testAnswer[index]) {
                isPass = false
            }
        })

        return isPass;

    } catch(e) {
        console.error("CardView's get API Test Result is Fail, please check you logic or WebSquare Engine");
    }
}

// removeAll, refresh
scwin.utilFuncTest = function() {
    cardView1.removeAll();
    var isRemove = cardView1._rows.length === 0;

    cardView1.refresh();
    var isRefresh = cardView1._rows.length > 0;
    var isPass = isRemove && isRefresh;

    console.log("utilFuncTest [removeAll, refresh] : [" + (isPass === true ? "PASS" : "FAIL") + "]")
    return isPass;
}

scwin.setPageSize_test = function() {
    cardView1.setPageSize(5)
    console.log("setPageSize : " + (cardView1.getPageSize() === 5 ? "[PASS]" : "[FAIL]"));
};

scwin.setPageIndex_test = function() {
    cardView1.setPageIndex(2)
    console.log("setPageIndex : " + (cardView1.getPageIndex(2) === 2 ? "[PASS]" : "[FAIL]"));
}

// DataList 양방향 바인딩 테스트
scwin.test_dataList = function() {

    var isPass = false;
    cardView1.setPageIndex(1);

    // setCellData
    dlt_test.setCellData(0, 'col9', "setCellData");
    var cell = cardView1.getCellComponentByColId(0, "col9").getValue();
    isPass = dlt_test.getCellData(0, "col9") === cell;
    scwin.printLog(isPass, 'setCellData');

    // setRowJSON
    dlt_test.setRowJSON(0, {"col1" : 2, "col9" : "setRowJSON"}, true);
    var row = cardView1.getCellComponentByColId(0, "col9").getValue();
    isPass = dlt_test.getRowJSON(0).col9 === row;
    scwin.printLog(isPass, 'setRowJSON');

   // setRowData 
    dlt_test.setRowData(0, [2, "test", "test", "test", 2, "test", 2,2,"test"]);
    var rowData = cardView1.getCellComponentByColId(0, "col2").getValue();
    isPass = dlt_test.getRowData(0)[1] === rowData;
    scwin.printLog(isPass, 'setRowData');

    // insertData
    dlt_test.insertData(0, [0, "insertData","insertData","insertData",0,"insertData",0,0,"insertData","insertData","2026-01-01","insertData","2026-01-01","insertData","insertData","/person3.png"]);
    var insertData = cardView1.getCellComponentByColId(0, "col2").getValue();
    isPass = dlt_test.getRowData(0)[1] === insertData;
    scwin.printLog(isPass, 'insertData');

    // insertJSON
    dlt_test.insertJSON(0, [{"col1": 2,"col2": "insertJSON","col3": "insertJSON","col4": "insertJSON","col5": 2,"col6": "insertJSON","col7": 2,"col8": 2,"col9": "insertJSON","col10": "insertJSON","col11": "2026-12-31","col12": "insertJSON","col13": "2026-12-31","col14": "insertJSON","col15": "insertJSON","col16": "/person3.png"}])
    var insertJSON = cardView1.getCellComponentByColId(0,"col2").getValue();
    isPass = dlt_test.getRowJSON(0).col2 === insertJSON;
    scwin.printLog(isPass, "insertJSON");

    // removeRow
    var before = dlt_test.getRowCount();
    var pageSize = cardView1.getPageSize();

    dlt_test.removeRow(0);

    var after = dlt_test.getRowCount();
    var afterCount = Math.ceil( after / cardView1.getPageSize() );
    isPass = afterCount === cardView1.pageList.getCount();
    if(before - 1 !== after) isPass = false;
    scwin.printLog(isPass, "removeRow");

    return isPass;
}

scwin.removeRows_click = function() {
    // removeRows
    var before = dlt_test.getRowCount();

    dlt_test.removeRows([0,1,2]);

    var after = dlt_test.getRowCount();
    var afterCount = Math.ceil( after / cardView1.getPageSize() );
    var isPass = afterCount === cardView1.pageList.getCount();
    if(before - 3 !== after) isPass = false;
    scwin.printLog(isPass, "removeRows");

    return isPass;
}

scwin.removeRange_click = function() {
    // removeRange
    var before = dlt_test.getRowCount();

    dlt_test.removeRange(0,2);
    var after= dlt_test.getRowCount();
    var afterCount = Math.ceil( after / cardView1.getPageSize());
    isPass = afterCount === cardView1.pageList.getCount();
    if(before - 3 !== after) isPass = false;
    scwin.printLog(isPass, "removeRanges");

    return isPass;
}

scwin.removeAll_click = function() {
    // removeAll
    dlt_test.removeAll();
    var isPass = cardView1._rows.length === 0;
    scwin.printLog(isPass, "removeAll");

    return isPass;
}

scwin.printLog = function(isPass, api) {
    if(isPass) {
        console.log("dataList Binding Test :: " + api + " [Pass]");
    } else {
        console.log("dataList Binding Test :: " + api + " [Fail]");
        console.error("TEST [FAIL]");
    }
}

